/*
 * Dense Jonker-Volgenant algorithm for the rectangular/square linear assignment
 * problem. Minimizes sum_i cost[i * n + col_of_row[i]].
 *
 * Based on the JV algorithm (Jonker & Volgenant 1987) with the implementation
 * structure of the classic lapjv code (Volgenant / Jonker).
 */
#include <stdlib.h>
#include <string.h>
#include <float.h>
#include <math.h>

#define BIG 1e18

int solve_lap(int n, const double *cost, int *col_of_row) {
    int i, j, k, l, i0, j0, j1, free_cnt, unmatched;
    double h, minv, v2, umin, umax;

    double *u = (double *)calloc(n, sizeof(double));       /* row duals */
    double *v = (double *)calloc(n, sizeof(double));       /* col duals */
    int *row_of_col = (int *)malloc(n * sizeof(int));      /* col -> row */
    int *free_rows = (int *)malloc(n * sizeof(int));
    int *pred = (int *)malloc(n * sizeof(int));            /* predecessor row of column in alternating tree */
    int *col_list = (int *)malloc(n * sizeof(int));        /* columns to scan */
    double *d = (double *)malloc(n * sizeof(double));      /* reduced distances */
    char *in_tree = (char *)calloc(n, 1);

    if (!u || !v || !row_of_col || !free_rows || !pred || !col_list || !d || !in_tree) {
        return -1;
    }
    for (j = 0; j < n; j++) row_of_col[j] = -1;
    for (i = 0; i < n; i++) col_of_row[i] = -1;

    /* ---------- COLUMN REDUCTION ---------- */
    for (j = n - 1; j >= 0; j--) {
        minv = BIG;
        i0 = 0;
        for (i = 0; i < n; i++) {
            double c = cost[(size_t)i * n + j];
            if (c < minv) { minv = c; i0 = i; }
        }
        v[j] = minv;
        if (col_of_row[i0] == -1) {
            /* assign column j to row i0 */
            col_of_row[i0] = j;
            row_of_col[j] = i0;
        } else {
            /* row already assigned; leave column free (reduction only) */
        }
    }

    /* ---------- REDUCTION TRANSFER ---------- */
    free_cnt = 0;
    for (i = 0; i < n; i++) {
        if (col_of_row[i] == -1) {
            free_rows[free_cnt++] = i;
        } else {
            j = col_of_row[i];
            /* u[i] = min over j of cost[i,j] - v[j], but at least the assigned one.
               Transfer: set u[i] so assigned reduced cost is 0, then if another
               column has smaller reduced cost, transfer. */
            minv = cost[(size_t)i * n + j] - v[j];
            v2 = BIG;
            j1 = -1;
            for (k = 0; k < n; k++) {
                if (k == j) continue;
                h = cost[(size_t)i * n + k] - v[k];
                if (h < v2) { v2 = h; j1 = k; }
            }
            /* assigned reduced cost relative */
            /* We want u[i] = cost[i, assigned] - v[assigned] after possible transfer.
               If second min < assigned reduced, transfer reduction to that column. */
            if (v2 < minv) {
                v[j] -= (minv - v2);
                /* after transfer, assigned reduced equals v2; u = v2 */
                u[i] = v2;
            } else {
                u[i] = minv;
            }
            (void)j1;
        }
    }

    /* ---------- AUGMENTING ROW REDUCTION ---------- */
    /* Repeat a couple of passes over free rows, greedily reducing and assigning. */
    for (l = 0; l < 2; l++) {
        int new_free = 0;
        int f;
        int *next_free = (int *)malloc(n * sizeof(int));
        for (f = 0; f < free_cnt; f++) {
            i = free_rows[f];
            /* find min and second min reduced cost */
            double mn = BIG, mn2 = BIG;
            int jmin = -1;
            const double *row = cost + (size_t)i * n;
            for (j = 0; j < n; j++) {
                h = row[j] - v[j];
                if (h < mn) {
                    mn2 = mn;
                    mn = h;
                    jmin = j;
                } else if (h < mn2) {
                    mn2 = h;
                }
            }
            u[i] = mn;
            if (mn2 < BIG / 2) {
                v[jmin] -= (mn2 - mn); /* make two smallest equal -> unique? actually increase attractiveness of jmin */
            }
            /* try to assign jmin */
            i0 = row_of_col[jmin];
            if (i0 == -1) {
                col_of_row[i] = jmin;
                row_of_col[jmin] = i;
            } else if (u[i0] - (cost[(size_t)i0 * n + jmin] - v[jmin]) > 1e-12) {
                /* row i0 has slack on this column after reduction; steal and free i0? 
                   Standard ARR: if the column is assigned, free the previous row and reassign. */
                col_of_row[i] = jmin;
                row_of_col[jmin] = i;
                col_of_row[i0] = -1;
                next_free[new_free++] = i0;
            } else {
                /* keep free */
                next_free[new_free++] = i;
            }
        }
        free_cnt = new_free;
        memcpy(free_rows, next_free, new_free * sizeof(int));
        free(next_free);
        if (free_cnt == 0) break;
    }

    /* ---------- AUGMENTATION (shortest augmenting paths) ---------- */
    for (f_idx_init(free_cnt, free_rows, n, cost, u, v, row_of_col, col_of_row, pred, col_list, d, in_tree), unmatched = 0;
         unmatched < free_cnt; ) {
        break; /* placeholder, real loop below */
    }
    /* redo augmentation cleanly */
    {
        int f;
        for (f = 0; f < free_cnt; f++) {
            int freerow = free_rows[f];
            int endcol = -1;
            int low, up;
            double min_d;
            /* Dijkstra over columns */
            for (j = 0; j < n; j++) {
                d[j] = cost[(size_t)freerow * n + j] - v[j];
                pred[j] = freerow;
                in_tree[j] = 0;
            }
            low = 0; up = 0;
            /* no columns scanned yet; we scan all each time (dense) */
            while (1) {
                /* find unscanned column with smallest d */
                min_d = BIG;
                j1 = -1;
                for (j = 0; j < n; j++) {
                    if (!in_tree[j] && d[j] < min_d) {
                        min_d = d[j];
                        j1 = j;
                    }
                }
                if (j1 < 0) break;
                in_tree[j1] = 1;
                i0 = row_of_col[j1];
                if (i0 == -1) {
                    endcol = j1;
                    break;
                }
                /* update distances through row i0 */
                double ui = cost[(size_t)i0 * n + j1] - v[j1] - min_d; /* u candidate */
                const double *row = cost + (size_t)i0 * n;
                for (j = 0; j < n; j++) {
                    if (in_tree[j]) continue;
                    h = row[j] - v[j] - ui;
                    if (h < d[j]) {
                        d[j] = h;
                        pred[j] = i0;
                    }
                }
                (void)low; (void)up; (void)col_list;
            }
            if (endcol < 0) {
                /* infeasible */
                free(u); free(v); free(row_of_col); free(free_rows);
                free(pred); free(col_list); free(d); free(in_tree);
                return -2;
            }
            /* update duals */
            for (j = 0; j < n; j++) {
                if (in_tree[j]) {
                    int r = row_of_col[j];
                    /* v[j] += d[j] - min_d ; u[r] -= d[j] - min_d */
                    double delta = d[j] - min_d;
                    v[j] += delta;
                    if (r >= 0) {
                        u[r] -= delta;
                    }
                }
            }
            u[freerow] = min_d; /* not strictly needed for primal */
            /* augment along pred */
            j = endcol;
            while (1) {
                i0 = pred[j];
                row_of_col[j] = i0;
                j1 = col_of_row[i0];
                col_of_row[i0] = j;
                j = j1;
                if (i0 == freerow) break;
            }
        }
    }

    free(u); free(v); free(row_of_col); free(free_rows);
    free(pred); free(col_list); free(d); free(in_tree);
    return 0;
}

/* dummy to satisfy earlier call - will not be used if we restructure. */
void f_idx_init(int a, int *b, int c, const double *d, double *e, double *f,
                int *g, int *h, int *i, int *j, double *k, char *l) { (void)a;(void)b;(void)c;(void)d;(void)e;(void)f;(void)g;(void)h;(void)i;(void)j;(void)k;(void)l; }
