/*
 * Dense minimum-cost assignment via Jonker-Volgenant shortest augmenting paths.
 * cost is row-major n*n doubles. On return col_of_row[i] is the assigned column.
 * Returns 0 on success.
 */
#include <stdlib.h>
#include <float.h>
#include <string.h>

int solve_lap(int n, const double *cost, int *col_of_row) {
    int i, j, f;
    const double BIG = 1e300;

    double *u = (double *)calloc((size_t)n, sizeof(double));
    double *v = (double *)calloc((size_t)n, sizeof(double));
    int *row_of_col = (int *)malloc((size_t)n * sizeof(int));
    int *pred = (int *)malloc((size_t)n * sizeof(int));
    double *d = (double *)malloc((size_t)n * sizeof(double));
    char *seen = (char *)malloc((size_t)n);

    if (!u || !v || !row_of_col || !pred || !d || !seen) return -1;

    for (j = 0; j < n; j++) row_of_col[j] = -1;
    for (i = 0; i < n; i++) col_of_row[i] = -1;

    /* Initialize column duals to column minima (column reduction). */
    for (j = 0; j < n; j++) {
        double m = BIG;
        for (i = 0; i < n; i++) {
            double c = cost[(size_t)i * n + j];
            if (c < m) m = c;
        }
        v[j] = m;
    }

    /* Greedy initial matching on reduced costs, rows in order. */
    for (i = 0; i < n; i++) {
        const double *row = cost + (size_t)i * n;
        double best = BIG;
        int bj = 0;
        for (j = 0; j < n; j++) {
            double r = row[j] - v[j];
            if (r < best) { best = r; bj = j; }
        }
        u[i] = best;
        if (row_of_col[bj] < 0) {
            row_of_col[bj] = i;
            col_of_row[i] = bj;
        }
    }

    /* Augment each free row by a shortest path in the equality/reduced graph. */
    for (f = 0; f < n; f++) {
        if (col_of_row[f] >= 0) continue;

        for (j = 0; j < n; j++) {
            d[j] = cost[(size_t)f * n + j] - v[j];
            pred[j] = f;
            seen[j] = 0;
        }

        int endcol = -1;
        double min_d = 0.0;
        while (1) {
            min_d = BIG;
            int j1 = -1;
            for (j = 0; j < n; j++) {
                if (!seen[j] && d[j] < min_d) {
                    min_d = d[j];
                    j1 = j;
                }
            }
            if (j1 < 0) break;
            seen[j1] = 1;
            int i0 = row_of_col[j1];
            if (i0 < 0) { endcol = j1; break; }

            /* slack of the matched edge of i0 relative to the current path cost */
            double base = cost[(size_t)i0 * n + j1] - v[j1];
            const double *row = cost + (size_t)i0 * n;
            for (j = 0; j < n; j++) {
                if (seen[j]) continue;
                double nd = row[j] - v[j] - base + min_d;
                if (nd < d[j]) {
                    d[j] = nd;
                    pred[j] = i0;
                }
            }
        }
        if (endcol < 0) {
            free(u); free(v); free(row_of_col); free(pred); free(d); free(seen);
            return -2;
        }

        /* Dual update: columns in the tree get + (d[j] - min_d). */
        for (j = 0; j < n; j++) {
            if (seen[j]) {
                double delta = d[j] - min_d;
                v[j] += delta;
                int r = row_of_col[j];
                if (r >= 0) u[r] -= delta;
            }
        }

        /* Augment. */
        j = endcol;
        while (1) {
            int i0 = pred[j];
            int prev = col_of_row[i0];
            row_of_col[j] = i0;
            col_of_row[i0] = j;
            if (i0 == f) break;
            j = prev;
        }
    }

    free(u); free(v); free(row_of_col); free(pred); free(d); free(seen);
    return 0;
}
