/*
 * Jonker-Volgenant dense LAP (square).
 * Faithful to the classic lapmod/lapjv structure:
 *   1. column reduction
 *   2. reduction transfer
 *   3. augmenting row reduction
 *   4. augmentation via Dijkstra with a todo list (not a full scan)
 *
 * cost: row-major n*n doubles
 * col_of_row[i] = assigned column
 */
#include <stdlib.h>
#include <string.h>
#include <float.h>

#define BIG 1.0e18

int solve_lap(int n, const double *cost, int *col_of_row) {
    int i, j, k, f, cnt, last, low, up;
    double h, minv, v2;

    double *u = (double *)calloc((size_t)n, sizeof(double));
    double *v = (double *)calloc((size_t)n, sizeof(double));
    int *row_of_col = (int *)malloc((size_t)n * sizeof(int));
    int *free_rows = (int *)malloc((size_t)n * sizeof(int));
    int *pred = (int *)malloc((size_t)n * sizeof(int));
    int *todo = (int *)malloc((size_t)n * sizeof(int));
    double *d = (double *)malloc((size_t)n * sizeof(double));
    char *ok = (char *)calloc((size_t)n, 1); /* column scanned */

    if (!u || !v || !row_of_col || !free_rows || !pred || !todo || !d || !ok)
        return -1;

    for (j = 0; j < n; ++j) row_of_col[j] = -1;
    for (i = 0; i < n; ++i) col_of_row[i] = -1;

    /* ---- column reduction: assign each column to an unassigned row with min cost ---- */
    for (j = n - 1; j >= 0; --j) {
        minv = cost[j]; /* row 0 */
        int mini = 0;
        for (i = 1; i < n; ++i) {
            double c = cost[(size_t)i * n + j];
            if (c < minv) { minv = c; mini = i; }
        }
        v[j] = minv;
        if (col_of_row[mini] == -1) {
            col_of_row[mini] = j;
            row_of_col[j] = mini;
        } else {
            /* already taken: mark column free by leaving row_of_col = -1, but v is set.
               To match classic reduction we still record the reduction; column stays free. */
            row_of_col[j] = -1;
        }
    }

    /* free rows */
    cnt = 0;
    for (i = 0; i < n; ++i) {
        if (col_of_row[i] == -1) free_rows[cnt++] = i;
        else {
            /* reduction transfer */
            j = col_of_row[i];
            minv = cost[(size_t)i * n + j] - v[j];
            v2 = BIG;
            int j2 = -1;
            for (k = 0; k < n; ++k) {
                if (k == j) continue;
                h = cost[(size_t)i * n + k] - v[k];
                if (h < v2) { v2 = h; j2 = k; }
            }
            if (v2 < minv) {
                v[j] -= (minv - v2);
                u[i] = v2;
            } else {
                u[i] = minv;
            }
            (void)j2;
        }
    }

    /* ---- augmenting row reduction, 2 passes ---- */
    for (int pass = 0; pass < 2; ++pass) {
        int newcnt = 0;
        int fend = cnt;
        for (f = 0; f < fend; ++f) {
            i = free_rows[f];
            const double *row = cost + (size_t)i * n;
            minv = BIG; v2 = BIG;
            int jmin = 0;
            for (j = 0; j < n; ++j) {
                h = row[j] - v[j];
                if (h < minv) { v2 = minv; minv = h; jmin = j; }
                else if (h < v2) { v2 = h; }
            }
            u[i] = minv;
            double thresh = v2 - minv;
            v[jmin] -= thresh; /* unique-ify the minimum */
            int i0 = row_of_col[jmin];
            if (i0 < 0) {
                row_of_col[jmin] = i;
                col_of_row[i] = jmin;
            } else {
                /* steal if previous owner's reduced cost is now strictly above u */
                double red_prev = cost[(size_t)i0 * n + jmin] - v[jmin];
                if (red_prev > u[i0] + 1e-12) {
                    row_of_col[jmin] = i;
                    col_of_row[i] = jmin;
                    col_of_row[i0] = -1;
                    free_rows[newcnt++] = i0;
                } else {
                    /* revert the dual change? Classic ARR always applies the reduction
                       and frees the previous row unconditionally when improving.
                       We use the standard rule: always reassign and free previous. */
                    /* undo: we already changed v. Standard algorithm always reassigns. */
                    row_of_col[jmin] = i;
                    col_of_row[i] = jmin;
                    col_of_row[i0] = -1;
                    free_rows[newcnt++] = i0;
                }
            }
        }
        cnt = newcnt;
        if (cnt == 0) break;
    }

    /* ---- augmentation ---- */
    for (f = 0; f < cnt; ++f) {
        int freerow = free_rows[f];
        const double *frow = cost + (size_t)freerow * n;

        for (j = 0; j < n; ++j) {
            d[j] = frow[j] - v[j];
            pred[j] = freerow;
            ok[j] = 0;
        }

        low = 0; up = 0;
        /* seed todo with all columns? No: Dijkstra with lazy scan of minimum.
           We keep an unscanned set implicitly and a ready list of improved columns.
           For the first pivot we must scan all columns once. After that only the todo list
           (columns whose d decreased) needs scanning — that's the JV trick. */
        int endcol = -1;
        double mind;
        int j1 = -1;
        /* first scan: all columns */
        mind = BIG;
        for (j = 0; j < n; ++j) {
            if (d[j] < mind) { mind = d[j]; j1 = j; }
        }
        while (1) {
            if (j1 < 0) { endcol = -1; break; }
            ok[j1] = 1;
            int i0 = row_of_col[j1];
            if (i0 < 0) { endcol = j1; break; }

            double base = cost[(size_t)i0 * n + j1] - v[j1] - mind;
            const double *row = cost + (size_t)i0 * n;
            /* scan only columns not yet in tree. The JV optimization: columns are
               partitioned; we scan all not-ok columns but skip those with d >= mind+something.
               Full scan of not-ok is O(n). With ~n augmentations this is O(n^3).
               The todo-list version: only re-check columns when we might improve them,
               which is still all of them the first time a row is expanded. The win comes
               from not re-scanning columns already known worse than the current minimum
               until an update could reach them. We implement the "scan list" version:

               Maintain `todo[low..up)` of columns that are candidates (d improved and not scanned).
               Initially all columns are candidates. */
            /* We'll do a proper todo implementation below; this loop is replaced. */
            (void)base; (void)row;
            break;
        }
        (void)endcol; (void)low; (void)up; (void)last;
    }

    /* Real augmentation, todo-list Dijkstra (Dial-like / JV scan). */
    for (f = 0; f < cnt; ++f) {
        int freerow = free_rows[f];
        const double *frow = cost + (size_t)freerow * n;
        for (j = 0; j < n; ++j) {
            d[j] = frow[j] - v[j];
            pred[j] = freerow;
            ok[j] = 0;
            todo[j] = j;
        }
        low = 0;
        up = n;          /* todo[0..n) are unscanned candidates, unordered */
        int endcol = -1;
        double mind = 0;

        while (low < up) {
            /* find min d in todo[low..up) */
            mind = d[todo[low]];
            int mpos = low;
            for (k = low + 1; k < up; ++k) {
                int jj = todo[k];
                if (d[jj] < mind) { mind = d[jj]; mpos = k; }
            }
            /* swap min to position low */
            j = todo[mpos];
            todo[mpos] = todo[low];
            todo[low] = j;
            ++low; /* scanned */
            ok[j] = 1;

            int i0 = row_of_col[j];
            if (i0 < 0) { endcol = j; break; }

            double base = cost[(size_t)i0 * n + j] - v[j];
            const double *row = cost + (size_t)i0 * n;
            /* update remaining candidates todo[low..up) */
            int p = low;
            while (p < up) {
                int jj = todo[p];
                double nd = row[jj] - v[jj] - base + mind;
                if (nd < d[jj]) {
                    d[jj] = nd;
                    pred[jj] = i0;
                }
                ++p;
            }
        }
        if (endcol < 0) {
            free(u); free(v); free(row_of_col); free(free_rows);
            free(pred); free(todo); free(d); free(ok);
            return -2;
        }

        for (j = 0; j < n; ++j) {
            if (ok[j]) {
                double delta = d[j] - mind;
                v[j] += delta;
                int r = row_of_col[j];
                if (r >= 0) u[r] -= delta;
            }
        }
        /* augment */
        j = endcol;
        while (1) {
            int i0 = pred[j];
            int prev = col_of_row[i0];
            row_of_col[j] = i0;
            col_of_row[i0] = j;
            if (i0 == freerow) break;
            j = prev;
        }
    }

    free(u); free(v); free(row_of_col); free(free_rows);
    free(pred); free(todo); free(d); free(ok);
    return 0;
}
