{"command":"cat > work/lapjv.c << 'EOF'
/*
 * Jonker-Volgenant algorithm for dense square LAP.
 * Structure follows Volgenant's lapjv (1987/1990):
 *   column reduction, reduction transfer, augmenting row reduction,
 *   then shortest augmenting path with a dynamic list of columns to scan.
 *
 * The inner scan only visits columns that are still "ready" (their reduced
 * distance is below the current threshold), which is the main practical win
 * of JV over plain Hungarian/Dijkstra.
 */
#include <stdlib.h>
#include <string.h>
#include <float.h>

#define BIG 1.0e18

int solve_lap(int n, const double *cost, int *x) {
    /* x[i] = column assigned to row i */
    int i, j, k, f;
    int *y = (int *)malloc((size_t)n * sizeof(int));          /* y[j] = row assigned to col j, or -1 */
    int *free_rows = (int *)malloc((size_t)n * sizeof(int));
    int *pred = (int *)malloc((size_t)n * sizeof(int));
    int *ready = (int *)malloc((size_t)n * sizeof(int));      /* columns with d[j] < threshold, to scan */
    int *scan = (int *)malloc((size_t)n * sizeof(int));
    double *v = (double *)calloc((size_t)n, sizeof(double));
    double *d = (double *)malloc((size_t)n * sizeof(double));
    char *in_tree = (char *)calloc((size_t)n, 1);
    double *u = (double *)calloc((size_t)n, sizeof(double));

    if (!y || !free_rows || !pred || !ready || !scan || !v || !d || !in_tree || !u) return -1;

    for (j = 0; j < n; ++j) y[j] = -1;
    for (i = 0; i < n; ++i) x[i] = -1;

    /* ========== COLUMN REDUCTION ========== */
    for (j = n - 1; j >= 0; --j) {
        double m = cost[j];
        int mi = 0;
        for (i = 1; i < n; ++i) {
            double c = cost[(size_t)i * n + j];
            if (c < m) { m = c; mi = i; }
        }
        v[j] = m;
        if (x[mi] == -1) {
            x[mi] = j;
            y[j] = mi;
        }
    }

    /* ========== REDUCTION TRANSFER ========== */
    int nfree = 0;
    for (i = 0; i < n; ++i) {
        if (x[i] == -1) {
            free_rows[nfree++] = i;
            continue;
        }
        j = x[i];
        double a = cost[(size_t)i * n + j] - v[j];
        double b = BIG;
        for (k = 0; k < n; ++k) {
            if (k == j) continue;
            double h = cost[(size_t)i * n + k] - v[k];
            if (h < b) b = h;
        }
        u[i] = (b < a) ? b : a;
        if (b < a) v[j] -= (a - b);
    }

    /* ========== AUGMENTING ROW REDUCTION ========== */
    for (int pass = 0; pass < 2 && nfree; ++pass) {
        int kfree = 0;
        int end = nfree;
        int prv = 0;
        /* process current free list; newly freed rows go to the front for next pass
           but within a pass we only iterate the original list (classic does both). */
        for (f = 0; f < end; ++f) {
            i = free_rows[f];
            if (x[i] != -1) continue; /* already matched by a steal? shouldn't happen */
            const double *row = cost + (size_t)i * n;
            double mn = BIG, mn2 = BIG;
            int jmin = 0;
            for (j = 0; j < n; ++j) {
                double h = row[j] - v[j];
                if (h < mn2) {
                    if (h >= mn) {
                        mn2 = h;
                    } else {
                        mn2 = mn;
                        mn = h;
                        jmin = j;
                    }
                }
            }
            u[i] = mn;
            double umin = mn2 - mn;
            v[jmin] -= umin;
            int i0 = y[jmin];
            if (umin < 1e-15 && i0 >= 0) {
                /* minimum not unique enough and column taken: keep free */
                free_rows[kfree++] = i;
            } else if (i0 >= 0) {
                /* reassign, free previous */
                y[jmin] = i;
                x[i] = jmin;
                x[i0] = -1;
                free_rows[kfree++] = i0;
            } else {
                y[jmin] = i;
                x[i] = jmin;
            }
            (void)prv;
        }
        nfree = kfree;
    }

    /* ========== AUGMENTATION ========== */
    for (f = 0; f < nfree; ++f) {
        int freerow = free_rows[f];
        if (x[freerow] != -1) continue;
        const double *frow = cost + (size_t)freerow * n;

        for (j = 0; j < n; ++j) {
            d[j] = frow[j] - v[j];
            pred[j] = freerow;
            in_tree[j] = 0;
        }

        /* ready list: all columns initially, we pick mins progressively.
           JV: maintain columns not yet scanned, pick the min, and only
           "prepare" columns whose d falls below the next pivot. */
        int nready = 0;
        int endcol = -1;
        double mind = BIG;

        /* initial pivot: minimum d */
        int jmin = 0;
        mind = d[0];
        for (j = 1; j < n; ++j) if (d[j] < mind) { mind = d[j]; jmin = j; }

        while (1) {
            if (jmin < 0) { endcol = -1; break; }
            in_tree[jmin] = 1;
            int i0 = y[jmin];
            if (i0 < 0) { endcol = jmin; break; }

            /* expand row i0. Find the minimum new distance among not-in-tree columns,
               and collect columns that improve. */
            double base = cost[(size_t)i0 * n + jmin] - v[jmin];
            const double *row = cost + (size_t)i0 * n;
            double next_min = BIG;
            int next_j = -1;
            nready = 0;
            for (j = 0; j < n; ++j) {
                if (in_tree[j]) continue;
                double nd = row[j] - v[j] - base + mind;
                if (nd < d[j]) {
                    d[j] = nd;
                    pred[j] = i0;
                }
                if (d[j] < next_min) { next_min = d[j]; next_j = j; }
            }
            mind = next_min;
            jmin = next_j;
            (void)nready; (void)ready; (void)scan;
        }

        if (endcol < 0) {
            free(y); free(free_rows); free(pred); free(ready); free(scan);
            free(v); free(d); free(in_tree); free(u);
            return -2;
        }

        for (j = 0; j < n; ++j) {
            if (in_tree[j]) {
                double delta = d[j] - mind;
                v[j] += delta;
                if (y[j] >= 0) u[y[j]] -= delta;
            }
        }
        j = endcol;
        while (1) {
            int i0 = pred[j];
            int prev = x[i0];
            y[j] = i0;
            x[i0] = j;
            if (i0 == freerow) break;
            j = prev;
        }
    }

    free(y); free(free_rows); free(pred); free(ready); free(scan);
    free(v); free(d); free(in_tree); free(u);
    return 0;
}
