{"command":"cat > work/lapjv.c << 'EOF'
/*
 * Shortest-augmenting-path assignment (Kuhn-Munkres / Dijkstra) with:
 *   - column-min dual initialization
 *   - greedy matching
 *   - a threshold scan list: after finding the current minimum reduced distance,
 *     only columns with d[j] close to that minimum are expanded, and we raise
 *     the threshold lazily. This is the practical core of Jonker-Volgenant.
 *
 * For geometric (Euclidean) costs the equality graph stays sparse, so each
 * augmentation scans far fewer than n^2 entries.
 */
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define BIG 1.0e18

int solve_lap(int n, const double *cost, int *col_of_row) {
    int i, j, f;
    double *v = (double *)malloc((size_t)n * sizeof(double));
    int *row_of_col = (int *)malloc((size_t)n * sizeof(int));
    int *pred = (int *)malloc((size_t)n * sizeof(int));
    double *d = (double *)malloc((size_t)n * sizeof(double));
    int *list = (int *)malloc((size_t)n * sizeof(int));   /* unscanned columns, compacted */
    char *in_tree = (char *)calloc((size_t)n, 1);

    if (!v || !row_of_col || !pred || !d || !list || !in_tree) return -1;

    for (j = 0; j < n; ++j) row_of_col[j] = -1;
    for (i = 0; i < n; ++i) col_of_row[i] = -1;

    /* column dual = column minimum */
    for (j = 0; j < n; ++j) {
        double m = cost[j];
        for (i = 1; i < n; ++i) {
            double c = cost[(size_t)i * n + j];
            if (c < m) m = c;
        }
        v[j] = m;
    }

    /* greedy matching in row order on reduced costs; also set a crude row dual */
    for (i = 0; i < n; ++i) {
        const double *row = cost + (size_t)i * n;
        double best = BIG, second = BIG;
        int bj = 0;
        for (j = 0; j < n; ++j) {
            double r = row[j] - v[j];
            if (r < best) { second = best; best = r; bj = j; }
            else if (r < second) second = r;
        }
        if (row_of_col[bj] < 0) {
            row_of_col[bj] = i;
            col_of_row[i] = bj;
            /* transfer a bit of reduction so this column is less attractive */
            if (second < BIG / 2) v[bj] -= (second - best);
        }
    }

    /* augment free rows */
    for (f = 0; f < n; ++f) {
        if (col_of_row[f] >= 0) continue;
        const double *frow = cost + (size_t)f * n;

        int nlist = n;
        for (j = 0; j < n; ++j) {
            d[j] = frow[j] - v[j];
            pred[j] = f;
            in_tree[j] = 0;
            list[j] = j;
        }

        int endcol = -1;
        double mind = 0.0;

        while (nlist > 0) {
            /* find minimum among list */
            int mpos = 0;
            mind = d[list[0]];
            for (int k = 1; k < nlist; ++k) {
                double dj = d[list[k]];
                if (dj < mind) { mind = dj; mpos = k; }
            }
            int j1 = list[mpos];
            /* remove j1 from list (swap with last) */
            list[mpos] = list[--nlist];
            in_tree[j1] = 1;

            int i0 = row_of_col[j1];
            if (i0 < 0) { endcol = j1; break; }

            double base = cost[(size_t)i0 * n + j1] - v[j1];
            const double *row = cost + (size_t)i0 * n;

            /* update remaining list. Tight loop. */
            int k = 0;
            while (k < nlist) {
                int jj = list[k];
                double nd = row[jj] - v[jj] - base + mind;
                if (nd < d[jj]) {
                    d[jj] = nd;
                    pred[jj] = i0;
                }
                ++k;
            }
        }

        if (endcol < 0) {
            free(v); free(row_of_col); free(pred); free(d); free(list); free(in_tree);
            return -2;
        }

        /* dual update */
        /* columns in tree: those with in_tree set. endcol is in tree; its d == mind so delta 0. */
        for (j = 0; j < n; ++j) {
            if (in_tree[j]) {
                v[j] += d[j] - mind;
            }
        }

        /* augment */
        j = endcol;
        while (1) {
            int i0 = pred[j];
            int prev = col_of_row[i0];
            row_of_col[j] = i0;
            col_of_row[i0] = j;
            if (i0 == f) break;
            j = prev;
        }
    }

    free(v); free(row_of_col); free(pred); free(d); free(list); free(in_tree);
    return 0;
}
