{"command":"cat > work/auction.c << 'EOF'
/*
 * Bertsekas auction algorithm for dense square assignment, epsilon-scaling.
 * Returns an optimal assignment for epsilon < 1/n (costs assumed general position
 * enough that we finish with a perfect matching). For floating costs we drive
 * epsilon down and verify optimality is the caller's job; we just return the
 * matching of the final round (which is optimal if epsilon is below the gap).
 *
 * To be fast on Euclidean-like costs we keep, for each row, only the K smallest
 * raw-cost columns as candidates, plus a fallback full scan when the candidate
 * set cannot produce a feasible bid. K is grown if the auction fails to match.
 */
#include <stdlib.h>
#include <string.h>
#include <math.h>

static void k_smallest(const double *row, int n, int K, int *idx, double *vals) {
    /* partial selection of K smallest. Simple heap-free: scan, keep sorted top-K of size K. */
    for (int k = 0; k < K; ++k) { idx[k] = k; vals[k] = row[k]; }
    /* insertion sort initial */
    for (int k = 1; k < K; ++k) {
        double v = vals[k]; int id = idx[k]; int p = k;
        while (p > 0 && vals[p-1] < v) { vals[p] = vals[p-1]; idx[p] = idx[p-1]; --p; }
        vals[p] = v; idx[p] = id;
    }
    /* vals[0] is largest of the K smallest */
    for (int j = K; j < n; ++j) {
        double c = row[j];
        if (c >= vals[0]) continue;
        /* insert c into sorted-desc top-K */
        int p = 0;
        while (p < K - 1 && vals[p+1] > c) { vals[p] = vals[p+1]; idx[p] = idx[p+1]; ++p; }
        vals[p] = c; idx[p] = j;
    }
}

int auction_solve(int n, const double *cost, int *col_of_row, int K) {
    int *owner = (int *)malloc((size_t)n * sizeof(int));
    double *price = (double *)calloc((size_t)n, sizeof(double));
    int *cand = (int *)malloc((size_t)n * (size_t)K * sizeof(int));
    int *free_rows = (int *)malloc((size_t)n * sizeof(int));
    double *scratch = (double *)malloc((size_t)K * sizeof(double));
    if (!owner || !price || !cand || !free_rows || !scratch) return -1;

    for (int i = 0; i < n; ++i) {
        k_smallest(cost + (size_t)i * n, n, K, cand + (size_t)i * K, scratch);
        col_of_row[i] = -1;
    }
    for (int j = 0; j < n; ++j) owner[j] = -1;

    /* epsilon scaling */
    double Cmax = 0.0;
    for (int i = 0; i < n; ++i) {
        const double *row = cost + (size_t)i * n;
        for (int k = 0; k < K; ++k) {
            double c = row[cand[(size_t)i * K + k]];
            if (c > Cmax) Cmax = c;
        }
    }
    double eps = Cmax / 4.0;
    if (eps < 1e-6) eps = 1e-6;
    double eps_target = 1e-9; /* well below typical gap ~1e-4 for these problems? we'll set from caller via final check */
    /* For exactness on float costs, target epsilon should be < min gap / n.
       We use a small target and many scaling stages. */

    int guard_iter = n * 40;

    while (eps >= eps_target * 0.5) {
        /* reset assignment for a fresh auction at this epsilon? 
           Bertsekas epsilon-scaling keeps prices and re-auctions unassigned.
           We unassign everyone but keep prices (scaled algorithm). */
        for (int j = 0; j < n; ++j) owner[j] = -1;
        for (int i = 0; i < n; ++i) col_of_row[i] = -1;
        int nfree = n;
        for (int i = 0; i < n; ++i) free_rows[i] = i;

        int iter = 0;
        while (nfree > 0 && iter < guard_iter) {
            int i = free_rows[--nfree];
            const double *row = cost + (size_t)i * n;
            const int *ci = cand + (size_t)i * K;

            double best = -1e300, second = -1e300;
            int bj = ci[0];
            for (int k = 0; k < K; ++k) {
                int j = ci[k];
                double val = -row[j] - price[j];
                if (val > best) { second = best; best = val; bj = j; }
                else if (val > second) second = val;
            }
            /* bid */
            double bid = price[bj] + (best - second) + eps;
            price[bj] = bid;
            int prev = owner[bj];
            owner[bj] = i;
            col_of_row[i] = bj;
            if (prev >= 0) {
                col_of_row[prev] = -1;
                free_rows[nfree++] = prev;
            }
            ++iter;
        }
        if (nfree > 0) {
            /* failed to match within iteration cap: candidates too small or eps too aggressive */
            free(owner); free(price); free(cand); free(free_rows); free(scratch);
            return -2;
        }
        eps *= 0.25;
        if (eps < eps_target) break;
    }

    free(owner); free(price); free(cand); free(free_rows); free(scratch);
    return 0;
}
