/*
 * Epsilon-scaling auction (Bertsekas) on a candidate edge set, with a full-row
 * fallback bid so the result is a true assignment optimum of the dense problem
 * once epsilon is below the optimality threshold.
 *
 * Prices are kept across scaling phases. Each phase starts from the previous
 * matching's prices and re-solves. Final epsilon is tiny.
 */
#include <stdlib.h>
#include <string.h>
#include <math.h>

static void k_smallest(const double *row, int n, int K, int *idx) {
    /* idx[0..K) = indices of K smallest, unsorted. Use a max-heap of size K. */
    /* simple O(n log K) via sorted insertion of size K (K small). vals descending. */
    double vals[256];
    if (K > 256) K = 256;
    for (int k = 0; k < K; ++k) { idx[k] = k; vals[k] = row[k]; }
    for (int k = 1; k < K; ++k) {
        double v = vals[k]; int id = idx[k]; int p = k;
        while (p > 0 && vals[p - 1] < v) { vals[p] = vals[p - 1]; idx[p] = idx[p - 1]; --p; }
        vals[p] = v; idx[p] = id;
    }
    for (int j = K; j < n; ++j) {
        double c = row[j];
        if (c >= vals[0]) continue;
        int p = 0;
        while (p < K - 1 && vals[p + 1] > c) { vals[p] = vals[p + 1]; idx[p] = idx[p + 1]; ++p; }
        vals[p] = c; idx[p] = j;
    }
}

int auction_solve(int n, const double *cost, int *col_of_row, int K) {
    if (K > 256) K = 256;
    if (K < 2) K = 2;
    int *owner = (int *)malloc((size_t)n * sizeof(int));
    double *price = (double *)calloc((size_t)n, sizeof(double));
    int *cand = (int *)malloc((size_t)n * (size_t)K * sizeof(int));
    int *free_rows = (int *)malloc((size_t)n * sizeof(int));
    if (!owner || !price || !cand || !free_rows) return -1;

    for (int i = 0; i < n; ++i)
        k_smallest(cost + (size_t)i * n, n, K, cand + (size_t)i * K);

    double Cmax = 0.0;
    for (size_t t = 0; t < (size_t)n * n; t += n) {
        /* sample a few; full max is safer and cheap enough once */
    }
    for (int i = 0; i < n; i += 1) {
        const double *row = cost + (size_t)i * n;
        double m = row[0];
        for (int j = 1; j < n; ++j) if (row[j] > m) m = row[j];
        if (m > Cmax) Cmax = m;
    }

    double eps = Cmax > 0 ? Cmax / 2.0 : 1.0;
    const double eps_final = 1.0 / (n * 1000.0); /* << 1/n */
    const int max_iter = n * 80;

    int rc = 0;
    while (1) {
        for (int j = 0; j < n; ++j) owner[j] = -1;
        for (int i = 0; i < n; ++i) { col_of_row[i] = -1; free_rows[i] = i; }
        int nfree = n;
        int iter = 0;
        int failed = 0;
        while (nfree > 0) {
            if (++iter > max_iter) { failed = 1; break; }
            int i = free_rows[--nfree];
            const double *row = cost + (size_t)i * n;

            /* bid over candidate set, but also consider the globally best if
               the candidate best is weak. We always scan the full row when
               eps is small (last two phases) to guarantee optimality.
               For speed, full scan only on the final phase. */
            double best = -1e300, second = -1e300;
            int bj = 0;
            if (eps <= eps_final * 4.0 + 1e-15) {
                for (int j = 0; j < n; ++j) {
                    double val = -row[j] - price[j];
                    if (val > best) { second = best; best = val; bj = j; }
                    else if (val > second) second = val;
                }
            } else {
                const int *ci = cand + (size_t)i * K;
                bj = ci[0];
                for (int k = 0; k < K; ++k) {
                    int j = ci[k];
                    double val = -row[j] - price[j];
                    if (val > best) { second = best; best = val; bj = j; }
                    else if (val > second) second = val;
                }
            }
            if (second < -1e290) second = best - 1.0;
            double raise = (best - second) + eps;
            price[bj] += raise;
            int prev = owner[bj];
            owner[bj] = i;
            col_of_row[i] = bj;
            if (prev >= 0) {
                col_of_row[prev] = -1;
                free_rows[nfree++] = prev;
            }
        }
        if (failed) { rc = -2; break; }
        if (eps <= eps_final) break;
        eps *= 0.2;
        if (eps < eps_final) eps = eps_final;
    }

    free(owner); free(price); free(cand); free(free_rows);
    return rc;
}
