/*
 * Epsilon-scaling auction for dense assignment.
 * Candidate lists (K nearest by raw cost) are used for bidding. If a person
 * cannot be matched within the iteration budget, K is grown and we retry.
 * The final epsilon is far below 1/n, and the last phase scans full rows so
 * the assignment is optimal for the dense cost (not just the candidate graph),
 * but only rows that bid do a scan, and with good prices few bids happen.
 */
#include <stdlib.h>
#include <string.h>
#include <math.h>

static void k_smallest(const double *row, int n, int K, int *idx) {
    double *vals = (double *)malloc((size_t)K * sizeof(double));
    for (int k = 0; k < K; ++k) { idx[k] = k; vals[k] = row[k]; }
    for (int k = 1; k < K; ++k) {
        double v = vals[k]; int id = idx[k]; int p = k;
        while (p > 0 && vals[p - 1] < v) { vals[p] = vals[p - 1]; idx[p] = idx[p - 1]; --p; }
        vals[p] = v; idx[p] = id;
    }
    for (int j = K; j < n; ++j) {
        double c = row[j];
        if (c >= vals[0]) continue;
        int p = 0;
        while (p < K - 1 && vals[p + 1] > c) { vals[p] = vals[p + 1]; idx[p] = idx[p + 1]; ++p; }
        vals[p] = c; idx[p] = j;
    }
    free(vals);
}

/* One auction phase. full_scan=1 scans every column; else candidate list.
   Returns 0 if a perfect matching is found. */
static int phase(int n, const double *cost, int *col_of_row, int *owner,
                 double *price, const int *cand, int K, double eps, int full_scan,
                 int *free_rows, int max_iter) {
    for (int j = 0; j < n; ++j) owner[j] = -1;
    for (int i = 0; i < n; ++i) { col_of_row[i] = -1; free_rows[i] = i; }
    int nfree = n;
    int iter = 0;
    while (nfree > 0) {
        if (++iter > max_iter) return -1;
        int i = free_rows[--nfree];
        const double *row = cost + (size_t)i * n;
        double best = -1e300, second = -1e300;
        int bj = 0;
        if (full_scan) {
            for (int j = 0; j < n; ++j) {
                double val = -row[j] - price[j];
                if (val > best) { second = best; best = val; bj = j; }
                else if (val > second) second = val;
            }
        } else {
            const int *ci = cand + (size_t)i * K;
            bj = ci[0];
            for (int k = 0; k < K; ++k) {
                int j = ci[k];
                double val = -row[j] - price[j];
                if (val > best) { second = best; best = val; bj = j; }
                else if (val > second) second = val;
            }
        }
        double raise = best - second + eps;
        if (raise < eps) raise = eps;
        price[bj] += raise;
        int prev = owner[bj];
        owner[bj] = i;
        col_of_row[i] = bj;
        if (prev >= 0) {
            col_of_row[prev] = -1;
            free_rows[nfree++] = prev;
        }
    }
    return 0;
}

int auction_solve(int n, const double *cost, int *col_of_row, int K0) {
    int *owner = (int *)malloc((size_t)n * sizeof(int));
    double *price = (double *)calloc((size_t)n, sizeof(double));
    int *free_rows = (int *)malloc((size_t)n * sizeof(int));
    if (!owner || !price || !free_rows) return -1;

    double Cmax = 0.0;
    for (int i = 0; i < n; ++i) {
        const double *row = cost + (size_t)i * n;
        for (int j = 0; j < n; ++j) if (row[j] > Cmax) Cmax = row[j];
    }
    double eps0 = (Cmax > 0 ? Cmax / 2.0 : 1.0);

    int K = K0 < 4 ? 4 : K0;
    int rc = -1;
    /* grow K until a matching is found through the scaling schedule */
    for (int attempt = 0; attempt < 5 && rc != 0; ++attempt) {
        if (K > n) K = n;
        int *cand = (int *)malloc((size_t)n * (size_t)K * sizeof(int));
        if (!cand) { rc = -1; break; }
        for (int i = 0; i < n; ++i)
            k_smallest(cost + (size_t)i * n, n, K, cand + (size_t)i * K);

        memset(price, 0, (size_t)n * sizeof(double));
        double eps = eps0;
        const double eps_final = 1.0 / (n * 500.0);
        rc = 0;
        int max_iter = n * (40 + attempt * 20);
        while (1) {
            int full = (eps <= eps_final * 1.01) || (K >= n);
            int pr = phase(n, cost, col_of_row, owner, price, cand, K, eps, full, free_rows, max_iter);
            if (pr != 0) { rc = -2; break; }
            if (eps <= eps_final) break;
            eps *= 0.25;
            if (eps < eps_final) eps = eps_final;
        }
        free(cand);
        if (rc == 0) break;
        if (K >= n) break;
        K *= 2;
    }

    free(owner); free(price); free(free_rows);
    return rc;
}
