/*
 * Exact assignment for costs whose optimum is supported on a sparse set of
 * locally-cheap edges (Euclidean distance matrices).
 *
 * Build a candidate graph (K cheapest edges per row and per column), solve it
 * by successive shortest augmenting paths with a binary heap, then repair any
 * dual violation by adding the violating edges and re-solving. A feasible dual
 * certifies optimality of the dense problem.
 */
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define BIG 1.0e300

typedef struct { double key; int col; } HN;
typedef struct { HN *a; int n, cap; } Heap;

static void heap_init(Heap *h, int cap) {
    h->a = (HN *)malloc((size_t)cap * sizeof(HN));
    h->n = 0; h->cap = cap;
}
static void heap_free(Heap *h) { free(h->a); }
static void heap_push(Heap *h, double key, int col) {
    if (h->n >= h->cap) {
        h->cap *= 2;
        h->a = (HN *)realloc(h->a, (size_t)h->cap * sizeof(HN));
    }
    int i = h->n++;
    while (i > 0) {
        int p = (i - 1) >> 1;
        if (h->a[p].key <= key) break;
        h->a[i] = h->a[p];
        i = p;
    }
    h->a[i].key = key; h->a[i].col = col;
}
static int heap_pop(Heap *h, double *key, int *col) {
    if (!h->n) return 0;
    *key = h->a[0].key; *col = h->a[0].col;
    HN last = h->a[--h->n];
    int i = 0;
    while (1) {
        int l = i * 2 + 1, r = l + 1, m = i;
        if (l < h->n && h->a[l].key < last.key) m = l;
        if (r < h->n && h->a[r].key < h->a[m].key) m = r;
        if (m == i) break;
        h->a[i] = h->a[m];
        i = m;
    }
    if (h->n) h->a[i] = last;
    return 1;
}

/* K smallest indices of row[0..n), written to idx[0..K). */
static void k_smallest(const double *row, int n, int K, int *idx) {
    double *vals = (double *)malloc((size_t)K * sizeof(double));
    for (int k = 0; k < K; ++k) { idx[k] = k; vals[k] = row[k]; }
    for (int k = 1; k < K; ++k) {
        double v = vals[k]; int id = idx[k]; int p = k;
        while (p > 0 && vals[p - 1] < v) { vals[p] = vals[p - 1]; idx[p] = idx[p - 1]; --p; }
        vals[p] = v; idx[p] = id;
    }
    for (int j = K; j < n; ++j) {
        double c = row[j];
        if (c >= vals[0]) continue;
        int p = 0;
        while (p < K - 1 && vals[p + 1] > c) { vals[p] = vals[p + 1]; idx[p] = idx[p + 1]; ++p; }
        vals[p] = c; idx[p] = j;
    }
    free(vals);
}

typedef struct {
    int *off;    /* row offset, length n+1 */
    int *cols;   /* concatenated neighbor columns */
    int n, nnz, cap;
} Graph;

static void graph_init(Graph *g, int n, int cap) {
    g->n = n; g->nnz = 0; g->cap = cap;
    g->off = (int *)malloc((size_t)(n + 1) * sizeof(int));
    g->cols = (int *)malloc((size_t)cap * sizeof(int));
}
static void graph_free(Graph *g) { free(g->off); free(g->cols); }

/* Build undirected-in-spirit candidate graph: K nearest columns per row AND
   K nearest rows per column. */
static void graph_build(Graph *g, int n, const double *cost, int K) {
    int cap_est = n * K * 2 + 8;
    int *tmp = (int *)malloc((size_t)n * sizeof(int));
    char *mark = (char *)calloc((size_t)n, 1);
    int *counts = (int *)calloc((size_t)n, sizeof(int));
    int *buf = (int *)malloc((size_t)cap_est * sizeof(int));
    int *row_off = (int *)malloc((size_t)(n + 1) * sizeof(int));

    /* first pass: count unique neighbors */
    int *neigh = (int *)malloc((size_t)(K * 2 + 4) * sizeof(int));
    for (int i = 0; i < n; ++i) {
        int cnt = 0;
        k_smallest(cost + (size_t)i * n, n, K, neigh);
        for (int k = 0; k < K; ++k) { neigh[K + k] = -1; }
        /* column side filled in second loop; count row side only here, column side below */
        for (int k = 0; k < K; ++k) mark[neigh[k]] = 1;
        cnt = K;
        counts[i] = cnt;
        for (int k = 0; k < K; ++k) mark[neigh[k]] = 0;
    }
    free(neigh);

    /* We'll do a simpler two-list merge per row below; recount properly. */
    free(counts);
    counts = (int *)calloc((size_t)n, sizeof(int));

    int *colK = (int *)malloc((size_t)n * (size_t)K * sizeof(int)); /* colK[j*K + t] = row */
    double *colv = (double *)malloc((size_t)n * sizeof(double));
    for (int j = 0; j < n; ++j) {
        /* K smallest rows for this column. Gather column into temp. */
        for (int i = 0; i < n; ++i) colv[i] = cost[(size_t)i * n + j];
        int *idx = colK + (size_t)j * K;
        k_smallest(colv, n, K, idx);
    }

    int *rowK = (int *)malloc((size_t)n * (size_t)K * sizeof(int));
    for (int i = 0; i < n; ++i)
        k_smallest(cost + (size_t)i * n, n, K, rowK + (size_t)i * K);

    /* count unique */
    for (int i = 0; i < n; ++i) {
        int cnt = 0;
        for (int k = 0; k < K; ++k) { int j = rowK[(size_t)i * K + k]; if (!mark[j]) { mark[j] = 1; ++cnt; } }
        for (int j = 0; j < n; ++j) {
            int *idx = colK + (size_t)j * K;
            for (int t = 0; t < K; ++t) if (idx[t] == i) {
                if (!mark[j]) { mark[j] = 1; ++cnt; }
                break;
            }
        }
        counts[i] = cnt;
        for (int j = 0; j < n; ++j) mark[j] = 0;
    }
    row_off[0] = 0;
    for (int i = 0; i < n; ++i) row_off[i + 1] = row_off[i] + counts[i];
    int nnz = row_off[n];
    int *cols = (int *)malloc((size_t)nnz * sizeof(int));
    int *fill = (int *)calloc((size_t)n, sizeof(int));
    for (int i = 0; i < n; ++i) {
        int base = row_off[i];
        int cnt = 0;
        for (int k = 0; k < K; ++k) {
            int j = rowK[(size_t)i * K + k];
            if (!mark[j]) { mark[j] = 1; cols[base + cnt++] = j; }
        }
        for (int j = 0; j < n; ++j) {
            int *idx = colK + (size_t)j * K;
            for (int t = 0; t < K; ++t) if (idx[t] == i) {
                if (!mark[j]) { mark[j] = 1; cols[base + cnt++] = j; }
                break;
            }
        }
        for (int t = 0; t < cnt; ++t) mark[cols[base + t]] = 0;
        fill[i] = cnt;
    }

    g->n = n; g->nnz = nnz; g->cap = nnz;
    g->off = row_off; g->cols = cols;

    free(tmp); free(mark); free(counts); free(buf); free(colK); free(colv); free(rowK); free(fill);
}

/* Append one edge; may realloc. Returns 0 if added or already present. */
static int graph_add(Graph *g, int row, int col) {
    int a = g->off[row], b = g->off[row + 1];
    for (int t = a; t < b; ++t) if (g->cols[t] == col) return 0;
    /* insert by rebuilding: shift tail. OK because repairs are rare. */
    if (g->nnz + 1 > g->cap) {
        g->cap = g->cap * 2 + 8;
        g->cols = (int *)realloc(g->cols, (size_t)g->cap * sizeof(int));
    }
    /* shift cols[b..nnz) right by 1 */
    memmove(g->cols + b + 1, g->cols + b, (size_t)(g->nnz - b) * sizeof(int));
    g->cols[b] = col;
    for (int i = row + 1; i <= g->n; ++i) g->off[i]++;
    g->nnz++;
    return 1;
}

static int sparse_ssp(int n, const double *cost, Graph *g,
                      int *col_of_row, int *row_of_col, double *v) {
    double *dist = (double *)malloc((size_t)n * sizeof(double));
    int *pred = (int *)malloc((size_t)n * sizeof(int));
    char *seen = (char *)malloc((size_t)n);
    Heap heap; heap_init(&heap, n * 4 + 8);
    if (!dist || !pred || !seen || !heap.a) return -1;

    for (int j = 0; j < n; ++j) row_of_col[j] = -1;
    for (int i = 0; i < n; ++i) col_of_row[i] = -1;
    memset(v, 0, (size_t)n * sizeof(double));

    for (int src = 0; src < n; ++src) {
        for (int j = 0; j < n; ++j) { dist[j] = BIG; seen[j] = 0; pred[j] = -1; }
        heap.n = 0;
        for (int t = g->off[src]; t < g->off[src + 1]; ++t) {
            int j = g->cols[t];
            double rc = cost[(size_t)src * n + j] - v[j];
            dist[j] = rc; pred[j] = src;
            heap_push(&heap, rc, j);
        }
        int end = -1;
        double endd = 0.0;
        while (heap.n) {
            double dk; int j;
            heap_pop(&heap, &dk, &j);
            if (seen[j] || dk > dist[j] + 1e-12) continue;
            seen[j] = 1;
            int i0 = row_of_col[j];
            if (i0 < 0) { end = j; endd = dk; break; }
            double base = cost[(size_t)i0 * n + j] - v[j];
            const double *row = cost + (size_t)i0 * n;
            for (int t = g->off[i0]; t < g->off[i0 + 1]; ++t) {
                int jj = g->cols[t];
                if (seen[jj]) continue;
                double nd = dk + row[jj] - v[jj] - base;
                if (nd < dist[jj]) {
                    dist[jj] = nd; pred[jj] = i0;
                    heap_push(&heap, nd, jj);
                }
            }
        }
        if (end < 0) {
            heap_free(&heap); free(dist); free(pred); free(seen);
            return -2;
        }
        for (int j = 0; j < n; ++j) if (seen[j]) v[j] += dist[j] - endd;
        int j = end;
        while (1) {
            int i0 = pred[j];
            int prev = col_of_row[i0];
            row_of_col[j] = i0;
            col_of_row[i0] = j;
            if (i0 == src) break;
            j = prev;
        }
    }
    heap_free(&heap); free(dist); free(pred); free(seen);
    return 0;
}

/* Scan all rows for reduced-cost violations. Add every violating edge (reduced
   cost < -tol) to the graph. Returns number added. */
static int add_violations(int n, const double *cost, Graph *g,
                          const int *col_of_row, const double *v, double tol) {
    int added = 0;
    for (int i = 0; i < n; ++i) {
        int mj = col_of_row[i];
        double ui = cost[(size_t)i * n + mj] - v[mj];
        const double *row = cost + (size_t)i * n;
        for (int j = 0; j < n; ++j) {
            double rc = row[j] - ui - v[j];
            if (rc < -tol) {
                if (graph_add(g, i, j)) ++added;
            }
        }
    }
    return added;
}

int solve_exact(int n, const double *cost, int *col_of_row, int K) {
    if (K < 4) K = 4;
    if (K > n) K = n;
    Graph g;
    graph_build(&g, n, cost, K);

    int *row_of_col = (int *)malloc((size_t)n * sizeof(int));
    double *v = (double *)malloc((size_t)n * sizeof(double));
    if (!row_of_col || !v) return -1;

    int rc = sparse_ssp(n, cost, &g, col_of_row, row_of_col, v);
    if (rc != 0) { graph_free(&g); free(row_of_col); free(v); return rc; }

    for (int rep = 0; rep < 32; ++rep) {
        int added = add_violations(n, cost, &g, col_of_row, v, 1e-8);
        if (added == 0) { graph_free(&g); free(row_of_col); free(v); return 0; }
        rc = sparse_ssp(n, cost, &g, col_of_row, row_of_col, v);
        if (rc != 0) { graph_free(&g); free(row_of_col); free(v); return rc; }
    }
    graph_free(&g); free(row_of_col); free(v);
    return -3;
}
