/*
 * Exact linear assignment specialized for Euclidean cost matrices.
 *
 * The optimal matching edge of each row is among its cheapest columns, so we
 * solve a sparse assignment (K nearest columns per row and per column) by
 * successive shortest augmenting paths, then add any dual-violating edges and
 * re-solve. A feasible dual certifies optimality of the dense problem.
 *
 * When the optimum is unique this returns the same basic optimal plan as
 * network simplex / Hungarian. These problem instances have a unique optimum.
 */
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define BIG 1.0e300

typedef struct { double key; int col; } HN;
typedef struct { HN *a; int n, cap; } Heap;

static void heap_init(Heap *h, int cap) {
    h->a = (HN *)malloc((size_t)cap * sizeof(HN));
    h->n = 0;
    h->cap = cap;
}
static void heap_free(Heap *h) { free(h->a); }
static void heap_swap(HN *x, HN *y) { HN t = *x; *x = *y; *y = t; }
static void heap_push(Heap *h, double key, int col) {
    if (h->n >= h->cap) {
        h->cap = h->cap * 2 + 4;
        h->a = (HN *)realloc(h->a, (size_t)h->cap * sizeof(HN));
    }
    int i = h->n++;
    h->a[i].key = key;
    h->a[i].col = col;
    while (i > 0) {
        int p = (i - 1) >> 1;
        if (h->a[p].key <= h->a[i].key) break;
        heap_swap(&h->a[p], &h->a[i]);
        i = p;
    }
}
static int heap_pop(Heap *h, double *key, int *col) {
    if (!h->n) return 0;
    *key = h->a[0].key;
    *col = h->a[0].col;
    h->a[0] = h->a[--h->n];
    int i = 0;
    while (1) {
        int l = i * 2 + 1, r = l + 1, m = i;
        if (l < h->n && h->a[l].key < h->a[m].key) m = l;
        if (r < h->n && h->a[r].key < h->a[m].key) m = r;
        if (m == i) break;
        heap_swap(&h->a[i], &h->a[m]);
        i = m;
    }
    return 1;
}

/* K smallest column indices of a length-n row. vals kept descending (max at 0). */
static void k_smallest(const double *row, int n, int K, int *idx, double *vals) {
    for (int k = 0; k < K; ++k) { idx[k] = k; vals[k] = row[k]; }
    for (int k = 1; k < K; ++k) {
        double v = vals[k]; int id = idx[k]; int p = k;
        while (p > 0 && vals[p - 1] < v) { vals[p] = vals[p - 1]; idx[p] = idx[p - 1]; --p; }
        vals[p] = v; idx[p] = id;
    }
    for (int j = K; j < n; ++j) {
        double c = row[j];
        if (c >= vals[0]) continue;
        int p = 0;
        while (p < K - 1 && vals[p + 1] > c) { vals[p] = vals[p + 1]; idx[p] = idx[p + 1]; ++p; }
        vals[p] = c; idx[p] = j;
    }
}

typedef struct {
    int *off, *cols;
    int n, nnz, cap;
} Graph;

static int graph_add(Graph *g, int row, int col) {
    int a = g->off[row], b = g->off[row + 1];
    for (int t = a; t < b; ++t) if (g->cols[t] == col) return 0;
    if (g->nnz + 1 > g->cap) {
        g->cap = g->cap * 2 + 8;
        g->cols = (int *)realloc(g->cols, (size_t)g->cap * sizeof(int));
    }
    memmove(g->cols + b + 1, g->cols + b, (size_t)(g->nnz - b) * sizeof(int));
    g->cols[b] = col;
    for (int i = row + 1; i <= g->n; ++i) g->off[i]++;
    g->nnz++;
    return 1;
}

static void graph_build(Graph *g, int n, const double *cost, int K) {
    int *rowK = (int *)malloc((size_t)n * (size_t)K * sizeof(int));
    int *colK = (int *)malloc((size_t)n * (size_t)K * sizeof(int));
    double *scratch = (double *)malloc((size_t)(n > K ? n : K) * sizeof(double));
    char *mark = (char *)calloc((size_t)n, 1);

    for (int i = 0; i < n; ++i)
        k_smallest(cost + (size_t)i * n, n, K, rowK + (size_t)i * K, scratch);
    for (int j = 0; j < n; ++j) {
        for (int i = 0; i < n; ++i) scratch[i] = cost[(size_t)i * n + j];
        k_smallest(scratch, n, K, colK + (size_t)j * K, scratch + n > scratch ? scratch : scratch);
        /* scratch is reused; k_smallest only needs K doubles of workspace and we passed
           the value buffer overlapping the column copy. Fix: use a separate vals buffer. */
    }
    free(scratch);

    /* The column k_smallest above is wrong because scratch overlaps. Redo columns properly. */
    free(colK);
    colK = (int *)malloc((size_t)n * (size_t)K * sizeof(int));
    double *colv = (double *)malloc((size_t)n * sizeof(double));
    double *kvals = (double *)malloc((size_t)K * sizeof(double));
    for (int j = 0; j < n; ++j) {
        for (int i = 0; i < n; ++i) colv[i] = cost[(size_t)i * n + j];
        k_smallest(colv, n, K, colK + (size_t)j * K, kvals);
    }

    int *counts = (int *)calloc((size_t)n, sizeof(int));
    for (int i = 0; i < n; ++i) {
        int cnt = 0;
        for (int k = 0; k < K; ++k) {
            int j = rowK[(size_t)i * K + k];
            if (!mark[j]) { mark[j] = 1; ++cnt; }
        }
        for (int j = 0; j < n; ++j) {
            int *idx = colK + (size_t)j * K;
            for (int t = 0; t < K; ++t) if (idx[t] == i) {
                if (!mark[j]) { mark[j] = 1; ++cnt; }
                break;
            }
        }
        counts[i] = cnt;
        for (int j = 0; j < n; ++j) mark[j] = 0;
    }
    int *off = (int *)malloc((size_t)(n + 1) * sizeof(int));
    off[0] = 0;
    for (int i = 0; i < n; ++i) off[i + 1] = off[i] + counts[i];
    int nnz = off[n];
    int *cols = (int *)malloc((size_t)(nnz + 16) * sizeof(int));
    for (int i = 0; i < n; ++i) {
        int base = off[i], cnt = 0;
        for (int k = 0; k < K; ++k) {
            int j = rowK[(size_t)i * K + k];
            if (!mark[j]) { mark[j] = 1; cols[base + cnt++] = j; }
        }
        for (int j = 0; j < n; ++j) {
            int *idx = colK + (size_t)j * K;
            for (int t = 0; t < K; ++t) if (idx[t] == i) {
                if (!mark[j]) { mark[j] = 1; cols[base + cnt++] = j; }
                break;
            }
        }
        for (int t = 0; t < cnt; ++t) mark[cols[base + t]] = 0;
    }
    g->n = n; g->nnz = nnz; g->cap = nnz + 16;
    g->off = off; g->cols = cols;
    free(mark); free(rowK); free(colK); free(colv); free(kvals); free(counts);
}

static int sparse_ssp(int n, const double *cost, Graph *g,
                      int *col_of_row, int *row_of_col, double *v) {
    double *dist = (double *)malloc((size_t)n * sizeof(double));
    int *pred = (int *)malloc((size_t)n * sizeof(int));
    char *seen = (char *)malloc((size_t)n);
    Heap heap; heap_init(&heap, n * 4 + 8);

    for (int j = 0; j < n; ++j) row_of_col[j] = -1;
    for (int i = 0; i < n; ++i) col_of_row[i] = -1;
    memset(v, 0, (size_t)n * sizeof(double));

    for (int src = 0; src < n; ++src) {
        for (int j = 0; j < n; ++j) { dist[j] = BIG; seen[j] = 0; pred[j] = -1; }
        heap.n = 0;
        for (int t = g->off[src]; t < g->off[src + 1]; ++t) {
            int j = g->cols[t];
            double rc = cost[(size_t)src * n + j] - v[j];
            dist[j] = rc; pred[j] = src;
            heap_push(&heap, rc, j);
        }
        int end = -1;
        double endd = 0.0;
        while (heap.n) {
            double dk; int j;
            heap_pop(&heap, &dk, &j);
            if (seen[j] || dk > dist[j] + 1e-12) continue;
            seen[j] = 1;
            int i0 = row_of_col[j];
            if (i0 < 0) { end = j; endd = dk; break; }
            double base = cost[(size_t)i0 * n + j] - v[j];
            const double *row = cost + (size_t)i0 * n;
            for (int t = g->off[i0]; t < g->off[i0 + 1]; ++t) {
                int jj = g->cols[t];
                if (seen[jj]) continue;
                double nd = dk + row[jj] - v[jj] - base;
                if (nd < dist[jj]) {
                    dist[jj] = nd; pred[jj] = i0;
                    heap_push(&heap, nd, jj);
                }
            }
        }
        if (end < 0) {
            heap_free(&heap); free(dist); free(pred); free(seen);
            return -2;
        }
        for (int j = 0; j < n; ++j) if (seen[j]) v[j] += dist[j] - endd;
        int j = end;
        while (1) {
            int i0 = pred[j];
            int prev = col_of_row[i0];
            row_of_col[j] = i0;
            col_of_row[i0] = j;
            if (i0 == src) break;
            j = prev;
        }
    }
    heap_free(&heap); free(dist); free(pred); free(seen);
    return 0;
}

static int add_violations(int n, const double *cost, Graph *g,
                          const int *col_of_row, const double *v, double tol) {
    int added = 0;
    for (int i = 0; i < n; ++i) {
        int mj = col_of_row[i];
        double ui = cost[(size_t)i * n + mj] - v[mj];
        const double *row = cost + (size_t)i * n;
        const double *vv = v;
        for (int j = 0; j < n; ++j) {
            if (row[j] - ui - vv[j] < -tol) {
                if (graph_add(g, i, j)) ++added;
            }
        }
    }
    return added;
}

int solve_exact(int n, const double *cost, int *col_of_row, int K) {
    if (K < 4) K = 4;
    if (K > n) K = n;
    Graph g;
    graph_build(&g, n, cost, K);
    int *row_of_col = (int *)malloc((size_t)n * sizeof(int));
    double *v = (double *)malloc((size_t)n * sizeof(double));
    int rc = sparse_ssp(n, cost, &g, col_of_row, row_of_col, v);
    if (rc != 0) { free(g.off); free(g.cols); free(row_of_col); free(v); return rc; }
    for (int rep = 0; rep < 8; ++rep) {
        int added = add_violations(n, cost, &g, col_of_row, v, 1e-8);
        if (!added) break;
        rc = sparse_ssp(n, cost, &g, col_of_row, row_of_col, v);
        if (rc != 0) { free(g.off); free(g.cols); free(row_of_col); free(v); return rc; }
    }
    /* confirm */
    if (add_violations(n, cost, &g, col_of_row, v, 1e-7)) {
        free(g.off); free(g.cols); free(row_of_col); free(v);
        return -3;
    }
    free(g.off); free(g.cols); free(row_of_col); free(v);
    return 0;
}
