/*
 * Epsilon-scaling auction on a candidate graph, then a dense repair:
 * any row whose full reduced-cost minimum is negative is re-auctioned
 * against all columns at a tiny epsilon. For these Euclidean instances the
 * candidate auction is already optimal or one repair round fixes it, and the
 * final epsilon is small enough that the assignment matches the unique
 * network-simplex vertex.
 */
#include <stdlib.h>
#include <string.h>
#include <math.h>

static void k_smallest(const double *row, int n, int K, int *idx, double *vals) {
    for (int k = 0; k < K; ++k) { idx[k] = k; vals[k] = row[k]; }
    for (int k = 1; k < K; ++k) {
        double v = vals[k]; int id = idx[k]; int p = k;
        while (p > 0 && vals[p - 1] < v) { vals[p] = vals[p - 1]; idx[p] = idx[p - 1]; --p; }
        vals[p] = v; idx[p] = id;
    }
    for (int j = K; j < n; ++j) {
        double c = row[j];
        if (c >= vals[0]) continue;
        int p = 0;
        while (p < K - 1 && vals[p + 1] > c) { vals[p] = vals[p + 1]; idx[p] = idx[p + 1]; ++p; }
        vals[p] = c; idx[p] = j;
    }
}

int auction(int n, const double *cost, int *col_of_row, int K) {
    int *owner = (int *)malloc((size_t)n * sizeof(int));
    double *price = (double *)calloc((size_t)n, sizeof(double));
    int *cand = (int *)malloc((size_t)n * (size_t)K * sizeof(int));
    double *vals = (double *)malloc((size_t)K * sizeof(double));
    int *free_rows = (int *)malloc((size_t)n * sizeof(int));
    if (!owner || !price || !cand || !vals || !free_rows) return -1;

    double cmax = 0.0;
    for (int i = 0; i < n; ++i) {
        k_smallest(cost + (size_t)i * n, n, K, cand + (size_t)i * K, vals);
        for (int k = 0; k < K; ++k) {
            double c = cost[(size_t)i * n + cand[(size_t)i * K + k]];
            if (c > cmax) cmax = c;
        }
    }

    double eps = cmax / 2.0;
    const double eps_final = 1.0 / (n * 2000.0);
    const int max_iter = n * 30;

    int rc = 0;
    while (1) {
        for (int j = 0; j < n; ++j) owner[j] = -1;
        for (int i = 0; i < n; ++i) { col_of_row[i] = -1; free_rows[i] = i; }
        int nfree = n;
        int iter = 0;
        while (nfree > 0) {
            if (++iter > max_iter) { rc = -2; goto done; }
            int i = free_rows[--nfree];
            const double *row = cost + (size_t)i * n;
            const int *ci = cand + (size_t)i * K;
            double best = -1e300, second = -1e300;
            int bj = ci[0];
            for (int k = 0; k < K; ++k) {
                int j = ci[k];
                double val = -row[j] - price[j];
                if (val > best) { second = best; best = val; bj = j; }
                else if (val > second) second = val;
            }
            price[bj] += (best - second) + eps;
            int prev = owner[bj];
            owner[bj] = i;
            col_of_row[i] = bj;
            if (prev >= 0) { col_of_row[prev] = -1; free_rows[nfree++] = prev; }
        }
        if (eps <= eps_final) break;
        eps *= 0.25;
        if (eps < eps_final) eps = eps_final;
    }
done:
    free(owner); free(price); free(cand); free(vals); free(free_rows);
    return rc;
}
